/**
 * Figentra Flow file contract:
 * Purpose: hold the provenance header to STA-1945 FR-3: each comment style by path, none for strict JSON; the header
 *   names fflow, the preset and version, the override when one shaped the file, and "do not edit; change
 *   .flow/overrides/"; it opens the file, as the front matter's first line in Markdown with front matter, after the
 *   shebang in a script.
 * Boundary: pure functions; no process, no network.
 * Runtime: node
 * Governing contract: ADR 0022; STA-1945.
 */
// @covers sta-1945:FR-3 sta-1945:AC-2 sta-1945:P-006
import { test } from "node:test";
import assert from "node:assert/strict";

import { commentStyle, headerText, withHeader } from "../lib/provenance.mjs";

const META = { preset: "stackra", version: "0.3.0" };

test("commentStyle: by path; strict JSON and unknown kinds carry none", () => {
  assert.equal(commentStyle(".github/workflows/fflow-approve.yml"), "#");
  assert.equal(commentStyle(".github/CODEOWNERS"), "#");
  assert.equal(commentStyle("lefthook.yaml"), "#");
  assert.equal(commentStyle("guard/rules.mjs"), "//");
  assert.equal(commentStyle("opencode.jsonc"), "//");
  assert.equal(commentStyle(".claude/skills/flow-plan/SKILL.md"), "frontmatter");
  assert.equal(commentStyle("page.html"), "html");
  assert.equal(commentStyle(".claude/settings.json"), undefined);
  assert.equal(commentStyle("logo.png"), undefined);
});

test("headerText: fflow, the preset and version, the override if any, and where to change it", () => {
  assert.equal(
    headerText(META),
    "Generated by fflow from the stackra preset 0.3.0: do not edit; change .flow/overrides/ and run `fflow sync`.",
  );
  assert.match(
    headerText({ ...META, override: ".flow/overrides/commands/flow-plan.md" }),
    /preset 0\.3\.0, shaped by \.flow\/overrides\/commands\/flow-plan\.md: do not edit; change \.flow\/overrides\//,
  );
});

test("withHeader: every comment-capable file starts with the header; strict JSON is unchanged", () => {
  const words = headerText(META);
  assert.equal(withHeader("a.yml", "on: push\n", META), `# ${words}\non: push\n`);
  assert.equal(withHeader("a.mjs", "export {};\n", META), `// ${words}\nexport {};\n`);
  assert.equal(withHeader("README.md", "# Title\n", META), `<!-- ${words} -->\n# Title\n`);
  assert.equal(withHeader("a.html", "<p></p>\n", META), `<!-- ${words} -->\n<p></p>\n`);
  assert.equal(
    withHeader("SKILL.md", "---\nname: flow-plan\n---\n\nBody\n", META),
    `---\n# ${words}\nname: flow-plan\n---\n\nBody\n`,
    "the front matter still opens the file",
  );
  assert.equal(withHeader("run.sh", "#!/bin/sh\necho\n", META), `#!/bin/sh\n# ${words}\necho\n`);
  assert.equal(withHeader(".claude/settings.json", '{ "a": 1 }\n', META), '{ "a": 1 }\n');
});
